# 云澜市桥梁养护管理平台 - 计划模块
from datetime import date


class SpanDossier:
    """单座桥梁的档案：桥名、结构形式、养护等级。"""

    def __init__(self, name: str, structure: str, grade: int):
        self.name = name
        self.structure = structure
        self.grade = grade


def schedule_span_repair(dossier: SpanDossier, window: date) -> dict:
    """安排一次桥面修补作业，返回工单字典。"""
    return {"桥名": dossier.name, "作业": "桥面修补", "窗口": window.isoformat()}


def next_patrol_date(last: date, grade: int) -> date:
    """按养护等级推算下一次日常巡查日期。"""
    gap = {1: 7, 2: 15, 3: 30}[grade]
    return date.fromordinal(last.toordinal() + gap)

